import React from 'react';

function Navbar() {
  return (
    <div style={styles.navbar}>
      <h2 style={styles.title}>Event Booking</h2>

      <div>
        <button style={styles.login}>Login</button>
        <button style={styles.register}>Register</button>
      </div>
    </div>
  );
}

const styles = {
  navbar: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: '16px 24px',
    background: '#ffffff',
    borderBottom: '1px solid #eee',
  },

  title: {
    color: '#FF4D00',   
    fontWeight: '700',
    fontSize: '24px',
  },

  login: {
    marginRight: '10px',
    padding: '8px 16px',
    border: '1px solid #FF4D00',
    background: 'white',
    color: '#FF4D00',
    borderRadius: '8px',
    cursor: 'pointer',
  },

  register: {
    padding: '8px 16px',
    border: 'none',
    background: '#FF4D00',
    color: 'white',
    borderRadius: '8px',
    cursor: 'pointer',
  },
};

export default Navbar;
